string shortestPalindrome(string s) {
    string r(s.rbegin(), s.rend()), t = s + "#" + r; vector<int> pi(t.size(), 0);
    for (size_t i = 1, k = 0; i < t.size(); i++) { while (k && t[i] != t[k]) k = pi[k-1]; if (t[i] == t[k]) k++; pi[i] = k; }
    string add = s.substr(pi.back()); reverse(add.begin(), add.end()); return add + s;
}
